const fs = require('node:fs/promises');
const { test, expect, expectScrollSettled } = require('./fixtures');

const sections = ['pupil-trends', 'forecast-checks', 'school-places', 'year-groups', 'budget', 'other-proposals', 'methodology'];
const chartSections = ['pupil-trends', 'school-places', 'year-groups'];
// Independently checked against the DfE May capacity files and January census.
// Keep these dated source checks separate from values generated by the page.
const sourceChecks = [
  { urn: '133343', name: 'Kew Riverside Primary School', rolls: [142, 107, 102, 90], capacity: 210 },
  { urn: '102884', name: 'Darell', rolls: [177, 193, 194, 177], capacity: 420 },
  { urn: '102921', name: "The King's", rolls: [366, 394, 398, 392], capacity: 420 },
];

async function activate(locator, hasTouch) {
  if (hasTouch) await locator.tap();
  else await locator.click();
}

async function openComparison(page, id = 'pupil-trends-detail') {
  const detail = page.locator('#' + id);
  if (!(await detail.evaluate(node => node.open))) await detail.locator(':scope > summary').click();
}

async function expectTrendMode(page, mode) {
  const counts = page.getByRole('button', { name: 'Pupil numbers', exact: true });
  const change = page.getByRole('button', { name: 'Percentage change', exact: true });
  await expect(counts).toHaveAttribute('aria-pressed', String(mode === 'count'));
  await expect(change).toHaveAttribute('aria-pressed', String(mode === 'change'));
  await expect(page.locator(`[data-trend-view="${mode}"]`)).toBeVisible();
  await expect(page.locator(`[data-trend-view="${mode === 'count' ? 'change' : 'count'}"]`)).toBeHidden();
  const charts = page.locator(`[data-trend-view="${mode}"] svg`);
  await expect(charts).toHaveCount(3);
  for (const chart of await charts.all()) {
    await expect(chart).toHaveAttribute('role', 'img');
    await expect(chart).toHaveAccessibleName(/\S/);
  }
  await expect(page.locator('#trend-status')).toContainText(mode === 'count' ? /pupil|number/i : /percentage|%/i);
}

