test('Understand: visible trend points, percentage baseline and local table match audited counts', async ({ page, hasTouch }) => {
  await page.goto('/understand.html');
  await openComparison(page);
  const normaliseNumber = value => Number(value.replaceAll('−', '-').replace(/[+%,\s]/g, ''));
  for (const expected of sourceChecks) {
    const chart = page.locator(`[data-trend-view="count"] figure[data-school="${expected.urn}"]`);
    expect((await chart.locator('.end-value').allTextContents()).map(normaliseNumber)).toEqual(expected.rolls);
  }
  await activate(page.getByRole('button', { name: 'Percentage change', exact: true }), hasTouch);
  for (const expected of sourceChecks) {
    const changes = expected.rolls.map(roll => Number(((roll / expected.rolls[0] - 1) * 100).toFixed(1)));
    const chart = page.locator(`[data-trend-view="change"] figure[data-school="${expected.urn}"]`);
    expect((await chart.locator('.end-value').allTextContents()).map(normaliseNumber)).toEqual(changes);
    expect(Number(await chart.locator('circle').first().getAttribute('cy'))).toBe(Number(await chart.locator('.baseline').getAttribute('y1')));
  }
  const summary = page.locator('#pupil-trends summary').filter({ hasText: /^View the local trend data$/ });
  await activate(summary, hasTouch);
  const table = summary.locator('..').locator('table');
  await expect(table.locator('tbody tr')).toHaveCount(3);
  for (const expected of sourceChecks) {
    const cells = await table.locator(`tr[data-school="${expected.urn}"] td`).allTextContents();
    expect(cells.slice(0, 4).map(normaliseNumber)).toEqual(expected.rolls);
    expect(normaliseNumber(cells.at(-1))).toBe(Number(((expected.rolls.at(-1) / expected.rolls[0] - 1) * 100).toFixed(1)));
  }
});

test('Understand: capacity and cohort graphics keep their dates, units and source values distinct', async ({ page }) => {
  await page.goto('/understand.html');
  await openComparison(page, 'school-places-detail');
  await openComparison(page, 'year-groups-detail');
  await expect(page.locator('#school-places .data-date')).toContainText('May 2025');
  await expect(page.locator('#year-groups .data-date')).toContainText('January 2026');
  for (const expected of sourceChecks) {
    const row = page.locator(`.place-row[data-school="${expected.urn}"]`);
    const roll = expected.rolls.at(-1);
    const unfilled = expected.capacity - roll;
    const occupied = (roll / expected.capacity * 100).toFixed(1);
    await expect(row.locator('.place-total')).toHaveText(`${roll} pupils / ${expected.capacity} reported places`);
    await expect(row.locator('svg')).toHaveAccessibleName(new RegExp(`${occupied.replace('.', '\\.')}% occupied; ${unfilled} unfilled places`));
    expect(Number(await row.locator('.place-filled').getAttribute('width'))).toBeCloseTo(roll / expected.capacity * 100, 3);
  }
  const kew = page.locator('.cohort-row[data-school="133343"]');
  await expect(kew.locator('p')).toContainText('84 pupils');
  await expect(kew.locator('.cohort-cell strong')).toHaveText([
    'Reception: 14', 'Year 1: 8', 'Year 2: 10', 'Year 3: 11', 'Year 4: 18', 'Year 5: 14', 'Year 6: 9',
  ]);
  await expect(page.locator('#year-groups .chart-footnote')).toContainText('not the September 2026 roll');
  await expect(page.locator('#school-places .chart-footnote')).toContainText('not a current vacancy list');
});

