test('Understand: published data keeps dated measurements and school-level totals consistent', async ({ page }) => {
  const response = await page.request.get('/understand-data.json');
  expect(response.ok()).toBe(true);
  const data = await response.json();
  expect(data.schemaVersion).toBe(1);
  expect(data.nearbyUrns).toEqual(sourceChecks.map(item => item.urn));
  expect(data.years.map(year => year.key)).toEqual(['202122', '202223', '202324', '202425']);
  expect(data.years.map(year => year.censusMonth)).toEqual(['2022-05', '2023-05', '2024-05', '2025-05']);
  expect(data.schools).toHaveLength(45);
  expect(new Set(data.schools.map(school => school.urn)).size).toBe(45);
  for (const expected of sourceChecks) {
    const school = data.schools.find(item => item.urn === expected.urn);
    expect(school.name).toContain(expected.name);
    expect(school.history.map(year => year.roll)).toEqual(expected.rolls);
    expect(school.capacity2025.capacity).toBe(expected.capacity);
    expect(school.capacity2025.roll).toBe(expected.rolls.at(-1));
  }
  const kew = data.schools.find(school => school.urn === '133343');
  expect(kew.cohorts2026.counts).toEqual([14, 8, 10, 11, 18, 14, 9]);
  expect(kew.cohorts2026.totalExcludingNursery).toBe(84);
  expect(kew.capacity2025.roll).toBe(90);
  expect(data.sources.find(source => source.id === 'dfe-capacity-2025').measurementDate).toBe('2025-05');
  expect(data.sources.find(source => source.id === 'dfe-census-2026').measurementDate).toBe('2026-01');
  for (const school of data.schools) {
    const capacity = school.capacity2025;
    expect(capacity.occupancyPercent).toBeCloseTo(capacity.roll / capacity.capacity * 100, 3);
    expect(capacity.unfilledPlaces).toBe(Math.max(0, capacity.capacity - capacity.roll));
    expect(capacity.pupilsOverCapacity).toBe(Math.max(0, capacity.roll - capacity.capacity));
    expect(school.cohorts2026.counts.reduce((sum, value) => sum + value, 0)).toBe(school.cohorts2026.totalExcludingNursery);
  }
  for (const total of data.borough) {
    const histories = data.schools.map(school => school.history.find(year => year.year === total.year));
    expect(histories).toHaveLength(total.schoolCount);
    expect(histories.reduce((sum, year) => sum + year.roll, 0)).toBe(total.roll);
    expect(histories.reduce((sum, year) => sum + year.capacity, 0)).toBe(total.capacity);
  }
});

